// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";

/**
 * @title EncryptedStorageRegistry
 * @notice Manages encrypted data blobs with gRPC service endpoint resolution
 * @dev Uses a linked-list index for service discovery ordering
 */
contract EncryptedStorageRegistry is Ownable {
    using ECDSA for bytes32;

    struct ServiceEndpoint {
        bytes32 encryptedUri;      // AES-256-GCM encrypted gRPC endpoint
        bytes32 nonce;             // Encryption nonce
        uint256 priority;          // Resolution priority
        bytes32 nextKey;           // Linked list pointer
        bool active;
    }

    struct StorageSlot {
        bytes32 dataHash;
        bytes encryptedPayload;
        uint256 timestamp;
        address authorizedReader;
    }

    mapping(bytes32 => ServiceEndpoint) public endpoints;
    mapping(bytes32 => StorageSlot) private storageSlots;
    mapping(address => bytes32[]) private userKeys;

    bytes32 public listHead;
    uint256 public endpointCount;
    uint256 public constant MAX_ENDPOINTS = 1000;

    // Priority resolution bucket tracking
    mapping(uint256 => bytes32[]) private priorityBuckets;
    uint256[] private activePriorities;

    event EndpointRegistered(bytes32 indexed key, uint256 priority);
    event DataStored(bytes32 indexed slot, address indexed owner);
    event ServiceResolved(bytes32 indexed key, uint256 gasUsed);

    modifier onlyAuthorized(bytes32 slot) {
        require(
            storageSlots[slot].authorizedReader == msg.sender || 
            msg.sender == owner(),
            "Unauthorized"
        );
        _;
    }

    constructor() Ownable() {}

    /**
     * @notice Register an encrypted gRPC service endpoint
     * @param key Unique identifier for the endpoint
     * @param encryptedUri AES-encrypted URI
     * @param nonce Encryption nonce
     * @param priority Service resolution priority (lower = higher priority)
     */
    function registerEndpoint(
        bytes32 key,
        bytes32 encryptedUri,
        bytes32 nonce,
        uint256 priority
    ) external onlyOwner {
        require(!endpoints[key].active, "Endpoint exists");
        require(endpointCount < MAX_ENDPOINTS, "Max endpoints reached");

        endpoints[key] = ServiceEndpoint({
            encryptedUri: encryptedUri,
            nonce: nonce,
            priority: priority,
            nextKey: bytes32(0),
            active: true
        });

        // Insert into priority bucket
        priorityBuckets[priority].push(key);
        _insertPriority(priority);

        // Maintain linked list ordering
        _insertOrdered(key, priority);
        endpointCount++;

        emit EndpointRegistered(key, priority);
    }

    /**
     * @notice Resolve service endpoints by priority range
     * @dev Traverses linked list - gas cost proportional to range size
     * @param minPriority Minimum priority to include
     * @param maxPriority Maximum priority to include  
     */
    function resolveServices(
        uint256 minPriority,
        uint256 maxPriority
    ) external returns (bytes32[] memory) {
        require(minPriority <= maxPriority, "Invalid range");

        uint256 gasStart = gasleft();
        bytes32[] memory results = new bytes32[](endpointCount);
        uint256 count = 0;

        // Traverse all priority buckets in range
        for (uint256 i = 0; i < activePriorities.length; i++) {
            uint256 p = activePriorities[i];
            if (p >= minPriority && p <= maxPriority) {
                bytes32[] storage bucket = priorityBuckets[p];
                for (uint256 j = 0; j < bucket.length; j++) {
                    if (endpoints[bucket[j]].active) {
                        results[count++] = bucket[j];
                    }
                }
            }
        }

        emit ServiceResolved(listHead, gasStart - gasleft());

        // Trim results array
        bytes32[] memory trimmed = new bytes32[](count);
        for (uint256 k = 0; k < count; k++) {
            trimmed[k] = results[k];
        }
        return trimmed;
    }

    /**
     * @notice Store encrypted data with access control
     */
    function storeEncrypted(
        bytes32 slot,
        bytes calldata encryptedPayload,
        address authorizedReader,
        bytes calldata signature
    ) external {
        bytes32 messageHash = keccak256(
            abi.encodePacked(slot, encryptedPayload, authorizedReader)
        );
        bytes32 ethSignedHash = messageHash.toEthSignedMessageHash();
        require(ethSignedHash.recover(signature) == msg.sender, "Invalid sig");

        storageSlots[slot] = StorageSlot({
            dataHash: keccak256(encryptedPayload),
            encryptedPayload: encryptedPayload,
            timestamp: block.timestamp,
            authorizedReader: authorizedReader
        });

        userKeys[msg.sender].push(slot);
        emit DataStored(slot, msg.sender);
    }

    /**
     * @notice Retrieve encrypted data
     */
    function retrieveEncrypted(
        bytes32 slot
    ) external view onlyAuthorized(slot) returns (bytes memory) {
        return storageSlots[slot].encryptedPayload;
    }

    /**
     * @notice Deregister endpoint and clean up
     */
    function deregisterEndpoint(bytes32 key) external onlyOwner {
        require(endpoints[key].active, "Not active");
        endpoints[key].active = false;
        endpointCount--;
        // Note: does not remove from priorityBuckets to save gas
        // resolveServices checks active flag
    }

    // --- Internal functions ---

    function _insertPriority(uint256 priority) internal {
        for (uint256 i = 0; i < activePriorities.length; i++) {
            if (activePriorities[i] == priority) return;
        }
        activePriorities.push(priority);
    }

    function _insertOrdered(bytes32 key, uint256 priority) internal {
        if (listHead == bytes32(0)) {
            listHead = key;
            return;
        }

        if (priority < endpoints[listHead].priority) {
            endpoints[key].nextKey = listHead;
            listHead = key;
            return;
        }

        bytes32 current = listHead;
        while (
            endpoints[current].nextKey != bytes32(0) &&
            endpoints[endpoints[current].nextKey].priority <= priority
        ) {
            current = endpoints[current].nextKey;
        }
        endpoints[key].nextKey = endpoints[current].nextKey;
        endpoints[current].nextKey = key;
    }
}
